<?php
require_once __DIR__.'/includes/layout.php';
require_once __DIR__.'/includes/import_csv.php';
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='import_csv') importer('tan','tan.php');
require_role(['SO']);
if($_SERVER['REQUEST_METHOD']==='POST')task('tan.php',function(PDO $db,array $u){if($u['vai_tro']!=='SO')throw new RuntimeException('Chỉ tài khoản Sở mới được phân bổ thí sinh.');$act=val('action');$ky=required_val('ma_ky_thi');$phong=required_val('ma_phong');$db->beginTransaction();try{
 $q=$db->prepare('SELECT ma_ky_thi,suc_chua FROM phong_thi WHERE ma_phong=? FOR UPDATE');$q->execute([$phong]);$room=$q->fetch();if(!$room||$room['ma_ky_thi']!==$ky)throw new RuntimeException('Phòng không thuộc kỳ thi.');
 if($act==='allocate'){$q=$db->prepare('SELECT ma_thi_sinh,ho_ten FROM thi_sinh WHERE ma_ky_thi=? AND ho_so_hop_le=1 AND ma_thi_sinh NOT IN (SELECT ma_thi_sinh FROM phan_bo_thi_sinh WHERE ma_ky_thi=?)');$q->execute([$ky,$ky]);$students=$q->fetchAll();if(!$students)throw new RuntimeException('Không có thí sinh đủ điều kiện chưa xếp phòng.');$collator=class_exists('Collator')?new Collator('vi_VN'):null;usort($students,fn($a,$b)=>$collator?$collator->compare($a['ho_ten'],$b['ho_ten']):strcmp(mb_strtolower($a['ho_ten']),mb_strtolower($b['ho_ten'])));$q=$db->prepare('SELECT COUNT(*) FROM phan_bo_thi_sinh WHERE ma_phong=? AND ma_ky_thi=?');$q->execute([$phong,$ky]);$used=(int)$q->fetchColumn();$slots=min(24,(int)$room['suc_chua'])-$used;if($slots<=0)throw new RuntimeException('Phòng đủ tối đa 24 thí sinh.');$created=0;foreach(array_slice($students,0,$slots) as $s){$next=$db->prepare('SELECT COALESCE(MAX(CAST(SUBSTRING(so_bao_danh,4) AS UNSIGNED)),0)+1 FROM phan_bo_thi_sinh WHERE ma_ky_thi=? AND so_bao_danh LIKE ?');$next->execute([$ky,'SBD%']);$sbd='SBD'.str_pad((string)$next->fetchColumn(),5,'0',STR_PAD_LEFT);$add=$db->prepare('INSERT INTO phan_bo_thi_sinh(ma_ky_thi,ma_thi_sinh,ma_phong,so_bao_danh) VALUES(?,?,?,?)');$add->execute([$ky,$s['ma_thi_sinh'],$phong,$sbd]);$created++;}audit($db,$u['id'],'PHAN_BO','Đã xếp '.$created.' thí sinh vào '.$phong);}
 elseif($act==='confirm'){$q=$db->prepare("UPDATE phan_bo_thi_sinh SET trang_thai='DA_XAC_NHAN' WHERE ma_ky_thi=? AND ma_phong=? AND trang_thai='DU_KIEN'");$q->execute([$ky,$phong]);if(!$q->rowCount())throw new RuntimeException('Chưa có phân bổ dự kiến cần xác nhận.');audit($db,$u['id'],'XAC_NHAN_PHAN_BO',$ky.' / '.$phong);}
 else throw new RuntimeException('Thao tác không hợp lệ.');$db->commit();}catch(Throwable $e){$db->rollBack();throw $e;}});
page_start('Phân bổ thí sinh vào phòng thi','tan');echo '<div class="note">QT06: Chỉ thí sinh có hồ sơ hợp lệ, xếp theo họ tên, tối đa 24/phòng, một phòng và một SBD duy nhất trong kỳ thi. Xếp phòng ở trạng thái <b>Dự kiến</b> trước khi xác nhận.</div><div class="panel"><h2>Xếp thí sinh chưa phân bổ vào phòng</h2>';form_open();echo '<input type="hidden" name="action" value="allocate">';select_field('ma_ky_thi','Kỳ thi','SELECT ma_ky_thi,ten_ky_thi FROM ky_thi','ma_ky_thi','ten_ky_thi');select_field('ma_phong','Phòng thi','SELECT ma_phong,ten_phong FROM phong_thi','ma_phong','ten_phong');form_close('Xếp vào phòng (dự kiến)');echo '</div><div class="panel"><h2>Xác nhận phân bổ</h2>';form_open();echo '<input type="hidden" name="action" value="confirm">';select_field('ma_ky_thi','Kỳ thi','SELECT ma_ky_thi,ten_ky_thi FROM ky_thi','ma_ky_thi','ten_ky_thi');select_field('ma_phong','Phòng thi','SELECT ma_phong,ten_phong FROM phong_thi','ma_phong','ten_phong');form_close('Xác nhận phân bổ phòng');echo '</div><div class="panel"><h2>Danh sách phân bổ</h2>';table_rows(db()->query('SELECT p.ma_ky_thi,t.ho_ten,p.so_bao_danh,r.ten_phong,p.trang_thai FROM phan_bo_thi_sinh p JOIN thi_sinh t ON t.ma_thi_sinh=p.ma_thi_sinh JOIN phong_thi r ON r.ma_phong=p.ma_phong ORDER BY p.ma_ky_thi,r.ma_phong,t.ho_ten')->fetchAll(),['Kỳ thi','Thí sinh','SBD','Phòng','Trạng thái']);echo '</div>';import_panel('tan','Phân bổ thí sinh');page_end();
